<script setup lang="ts">
import Swal from 'sweetalert2'
const emit=defineEmits<{refresh:[]}>()
const rows=ref<any[]>([]),selected=ref<any|null>(null),payments=ref<any[]>([]),busy=ref(false),paymentModal=ref(false)
const form=reactive({amountMinor:0,paymentDate:new Date().toISOString().slice(0,10),method:'',reference:'',notes:''})
const money=(n:number)=>new Intl.NumberFormat('en-TZ',{maximumFractionDigits:0}).format(Number(n)||0)+' TZS'
async function load(){const r:any=await window.api!.billing!.list();if(!r.ok)throw new Error(r.error.message);rows.value=r.data||[]}
async function choose(row:any){selected.value=row;const r:any=await window.api!.billing!.payments(row.id);if(!r.ok)return Swal.fire({icon:'error',title:'Could not load payments',text:r.error.message});payments.value=r.data||[]}
async function add(){if(!selected.value||form.amountMinor<=0)return Swal.fire({icon:'warning',title:'Enter a payment amount'});busy.value=true;const r:any=await window.api!.billing!.add({recordId:selected.value.id,amountMinor:form.amountMinor,paymentDate:form.paymentDate,method:form.method,reference:form.reference,notes:form.notes});busy.value=false;if(!r.ok)return Swal.fire({icon:'error',title:'Payment not saved',text:r.error.message});Object.assign(form,{amountMinor:0,paymentDate:new Date().toISOString().slice(0,10),method:'',reference:'',notes:''});paymentModal.value=false;await load();await choose(rows.value.find((row:any)=>row.id===selected.value.id)||selected.value);emit('refresh');await Swal.fire({icon:'success',title:'Payment recorded',timer:1800,showConfirmButton:false})}
async function remove(id:number){const result=await Swal.fire({title:'Delete this payment?',icon:'warning',showCancelButton:true,confirmButtonText:'Delete'});if(!result.isConfirmed)return;const r:any=await window.api!.billing!.remove(id);if(!r.ok)return Swal.fire({icon:'error',title:'Could not delete payment',text:r.error.message});await load();await choose(rows.value.find((row:any)=>row.id===selected.value.id)||selected.value);emit('refresh');await Swal.fire({icon:'success',title:'Payment deleted',timer:1800,showConfirmButton:false})}
watch(selected,row=>row&&choose(row))
onMounted(load)
</script>
<template><div class="billing"><article class="orders"><h2>Orders</h2><button v-for="row in rows" :key="row.id" :class="{active:selected?.id===row.id}" @click="choose(row)"><span><strong>{{row.record_number||row.client_name}}</strong><small>{{row.client_name}}</small></span><span><b>{{money(row.grand_total_minor-row.paid_minor)}}</b><em>{{row.payment_status}}</em></span></button></article><article class="payment"><template v-if="selected"><h2>Payments · {{selected.record_number||selected.client_name}}</h2><div class="summary"><span>Total<b>{{money(selected.grand_total_minor)}}</b></span><span>Paid<b>{{money(selected.paid_minor)}}</b></span><span>Balance<b>{{money(selected.grand_total_minor-selected.paid_minor)}}</b></span></div><button class="record" :disabled="busy||selected.paid_minor>=selected.grand_total_minor" @click="paymentModal=true">Record payment</button><table><thead><tr><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th><th></th></tr></thead><tbody><tr v-for="p in payments" :key="p.id"><td>{{p.payment_date}}</td><td>{{money(p.amount_minor)}}</td><td>{{p.method||'—'}}</td><td>{{p.reference||'—'}}</td><td><button class="delete" @click="remove(p.id)">Delete</button></td></tr></tbody></table></template><p v-else>Select an order to view or record payments.</p></article><div v-if="paymentModal" class="shade" @mousedown.self="paymentModal=false"><form class="modal" @submit.prevent="add"><header><div><small>PAYMENT</small><h2>Record payment</h2></div><button type="button" @click="paymentModal=false">×</button></header><div class="fields"><label>Amount (TZS)<input v-model.number="form.amountMinor" type="number" min="1" :max="selected?.grand_total_minor-selected?.paid_minor" required></label><label>Payment date<input v-model="form.paymentDate" type="date" required></label><label>Method<select v-model="form.method"><option value="">Select method</option><option>Cash</option><option>Bank transfer</option><option>Mobile money</option><option>Card</option></select></label><label>Reference<input v-model="form.reference"></label><label class="wide">Notes<textarea v-model="form.notes" rows="3"></textarea></label></div><footer><button type="button" @click="paymentModal=false">Cancel</button><button class="record" :disabled="busy">Save payment</button></footer></form></div></div></template>
<style scoped>.billing{display:grid;grid-template-columns:320px 1fr;gap:16px}.orders,.payment{background:#fff;border:1px solid var(--border);border-radius:12px;padding:16px}.orders>button{width:100%;display:flex;justify-content:space-between;text-align:left;border:0;border-bottom:1px solid var(--border);background:none;padding:12px 8px;cursor:pointer}.orders>button.active{background:#edf8f3;border-radius:8px}.orders small{display:block;color:var(--muted)}em{display:block;font-size:10px;font-style:normal;color:var(--brand)}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px 0}.summary span{background:#f7f2e8;padding:10px;border-radius:8px}.summary b{display:block;margin-top:4px}form{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:16px}label{display:grid;gap:5px;font-size:12px;font-weight:700}input{border:1px solid var(--border);padding:9px;border-radius:7px}.wide{grid-column:span 2}form button{align-self:end;border:0;background:var(--brand);color:#fff;border-radius:7px;font-weight:800}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid var(--border)}.delete{border:0;background:none;color:#b44545;font-weight:800}@media(max-width:900px){.billing{grid-template-columns:1fr}form{grid-template-columns:1fr 1fr}} .record{border:0;background:var(--brand);color:#fff;border-radius:7px;padding:10px 14px;font-weight:800;margin:8px 0}.shade{position:fixed;inset:0;background:rgba(15,23,42,.48);display:grid;place-items:center;z-index:50}.modal{width:min(560px,calc(100vw - 32px));background:#fff;border-radius:12px;padding:20px}.modal header,.modal footer{display:flex;justify-content:space-between;align-items:center}.modal header button{border:0;background:none;font-size:22px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.fields .wide{grid-column:span 2}textarea,select{border:1px solid var(--border);padding:9px;border-radius:7px}.modal footer{margin-top:16px}.modal footer button{border:0;border-radius:7px;padding:9px 14px;font-weight:800}</style>
